with.script:
// No channel post from here: cmt-verdict posts one short message
// after AI triage has judged the failures (green if flaky, red
// only if blocking). Set outputs before rethrowing so the verdict
// job still gets the report link and totals on a red run.
let result;
try {
  result = await require('./e2e/utils/tsio-report-status.js')({
    core, context, github,
    compositeIdentity: JSON.parse(process.env.TSIO_COMPOSITE_IDENTITY),
    totalReportsExpected: parseInt(process.env.TSIO_TOTAL_REPORTS_EXPECTED, 10),
    commitStatusContext: process.env.COMMIT_STATUS_CONTEXT,
    perOsCommitStatuses: false,
    upstreamJobsSucceeded: process.env.UPSTREAM_JOBS_SUCCEEDED === 'true',
    failOnTestFailures: true,
    notifyChannel: false,
  });
} catch (error) {
  core.setOutput('report-url', error.reportUrl || '');
  core.setOutput('stats', JSON.stringify(error.stats || {}));
  core.setOutput('summary-error', error.message);
  throw error;
}
core.setOutput('report-url', result.reportUrl || '');
core.setOutput('stats', JSON.stringify(result.stats || {}));
core.info(`TSIO report ${result.reportUrl}: ${result.status} (${JSON.stringify(result.stats)})`);

const fs = require('fs');
const path = require('path');
const {foldCmtVerdicts, formatCmtVerdictMessage} = require('./e2e/utils/cmt-triage-verdict.js');
const {postMattermostWebhook, buildWorkflowRunUrl} = require('./e2e/utils/cmt-channel-notify.js');

const compositeIdentity = JSON.parse(process.env.TSIO_COMPOSITE_IDENTITY);
const expectedLanes = (JSON.parse(process.env.CMT_TRIAGE_MATRIX || '{"include":[]}').include) || [];

const lanes = [];
try {
  const files = fs.readdirSync('cmt-triage-verdicts').filter((file) => file.endsWith('.json'));
  for (const file of files) {
    try {
      lanes.push(JSON.parse(fs.readFileSync(path.join('cmt-triage-verdicts', file), 'utf8')));
    } catch (error) {
      core.warning(`Could not parse triage verdict artifact ${file}: ${error.message}`);
    }
  }
} catch (error) {
  core.info(`No triage verdict artifacts: ${error.message}`);
}

let stats = {};
try {
  stats = JSON.parse(process.env.STATS || '{}');
} catch {
  core.warning('Could not parse TSIO stats output; counts will read as 0');
}

const fold = foldCmtVerdicts({
  lanes,
  expectedLanes,
  expectTriage: process.env.EXPECT_TRIAGE === 'true',
  stats,
  upstreamJobsSucceeded: process.env.UPSTREAM_JOBS_SUCCEEDED === 'true',
});
core.info(`CMT verdict: ${fold.state}/${fold.kind} — ${fold.statusDescription}`);

const reportUrl = process.env.REPORT_URL || '';
await github.rest.repos.createCommitStatus({
  owner: context.repo.owner,
  repo: context.repo.repo,
  sha: compositeIdentity.commit_sha,
  state: fold.commitStatusState,
  context: 'e2e/compatibility-matrix-testing',
  description: fold.statusDescription.slice(0, 140),
  target_url: reportUrl || buildWorkflowRunUrl(compositeIdentity),
});

const text = formatCmtVerdictMessage({
  fold,
  compositeIdentity,
  stats,
  reportUrl,
  runUrl: buildWorkflowRunUrl(compositeIdentity),
});
await core.summary.addRaw(`## Desktop CMT verdict\n\n${text}`).write();
await postMattermostWebhook({core, webhookUrl: process.env.MATTERMOST_CMT_WEBHOOK_URL || '', text});

const fs = require('fs');
const marker = '<!-- docs-impact-analysis -->';
const prNumber = context.payload.pull_request.number;
const analysisFile = `${process.env.RUNNER_TEMP}/docs-impact-result.md`;
let body = '';
if (fs.existsSync(analysisFile)) {
  body = fs.readFileSync(analysisFile, 'utf8').trim();
}
const validAssessments = new Set([
  'No Documentation Changes Needed',
  'Documentation Updates Recommended',
  'Documentation Updates Required',
]);
 const overallAssessment =
   body.match(/^\*\*Overall Assessment:\*\*\s*(.+)$/m)?.[1]?.trim();
const analysisFailed =
  process.env.ANALYSIS_OUTCOME !== 'success' ||
  !body ||
  !validAssessments.has(overallAssessment);
 const needsDocs =
   overallAssessment === 'Documentation Updates Recommended' ||
   overallAssessment === 'Documentation Updates Required';
let commentBody;
if (!analysisFailed && needsDocs) {
  commentBody = `${marker}\n<details>\n<summary>Documentation Impact Analysis — updates needed</summary>\n\n${body}\n</details>`;
} else if (analysisFailed) {
  const runUrl = `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`;
  commentBody = `${marker}\n<details>\n<summary>Documentation Impact Analysis — analysis failed</summary>\n\n` +
    `The automated documentation impact analysis could not be completed. ` +
    `Please review this PR manually for documentation impact.\n\n` +
    `[View workflow run](${runUrl})\n</details>`;
}
const { data: comments } = await github.rest.issues.listComments({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: prNumber,
});
const existing = comments.find(c => c.body?.includes(marker));
if (commentBody) {
  if (existing) {
    await github.rest.issues.updateComment({
      owner: context.repo.owner,
      repo: context.repo.repo,
      comment_id: existing.id,
      body: commentBody,
    });
  } else {
    await github.rest.issues.createComment({
      owner: context.repo.owner,
      repo: context.repo.repo,
      issue_number: prNumber,
      body: commentBody,
    });
  }
} else if (existing) {
  const staleBody = `${marker}\n<details>\n<summary>Documentation Impact Analysis — no longer needed</summary>\n\n` +
    `A previous automated documentation impact comment exists, but the latest analysis determined that no documentation changes are needed.\n\n` +
    `The \`Docs/Needed\` label may still be present from the earlier analysis. A maintainer can remove it after confirming no docs updates are required.\n</details>`;
  await github.rest.issues.updateComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    comment_id: existing.id,
    body: staleBody,
  });
}
const label = 'Docs/Needed';
const { data: issueLabels } = await github.rest.issues.listLabelsOnIssue({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: prNumber,
});
const hasLabel = issueLabels.some(l => l.name === label);
if (needsDocs && !hasLabel) {
  await github.rest.issues.addLabels({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: prNumber,
    labels: [label],
  });
}

const {owner, repo} = context.repo;
const label = process.env.OVERRIDE_LABEL;
const dispatched = context.eventName === 'workflow_dispatch';
const prNumber = dispatched ? Number(process.env.DISPATCH_PR) : context.payload.pull_request.number;
// Decide from the PR's current state, not the event, so a queued run acts on what is true now.
const {data: pr} = await github.rest.pulls.get({owner, repo, pull_number: prNumber});
const action = dispatched ? 'dispatch' : context.payload.action;
const eventLabel = dispatched ? '' : (context.payload.label?.name || '');

core.setOutput('mode', 'none');
core.setOutput('dry_run', process.env.DRY_RUN === 'true' ? 'true' : 'false');
core.setOutput('pr_number', String(pr.number));
core.setOutput('head_sha', pr.head.sha);
core.setOutput('head_repo', pr.head.repo?.full_name || '');
core.setOutput('head_ref', pr.head.ref);

if (pr.head.repo?.full_name === `${owner}/${repo}`) {
  core.info(`PR #${pr.number} is not from a fork; e2e-pr-trigger.yml handles it.`);
  return;
}
// The e2e/* contexts are required by the master branch protection.
if (pr.base.ref !== 'master') {
  core.info(`PR #${pr.number} targets ${pr.base.ref}, which requires no E2E status; nothing to do.`);
  return;
}

const hasWriteAccess = async (username) => {
  if (!username) {
    return false;
  }
  try {
    const {data} = await github.rest.repos.getCollaboratorPermissionLevel({owner, repo, username});
    // `permission` is the base level (maintain reads as write, triage as read), so custom roles work too.
    return ['admin', 'write'].includes(data.permission);
  } catch (err) {
    core.warning(`Permission lookup for ${username}: ${err.message}`);
    return false;
  }
};
const reset = async (why) => {
  core.setOutput('mode', 'pending');
  core.info(`Fork PR #${pr.number}: ${why}; resetting any waived contexts.`);
};

if (!pr.labels.some((l) => l.name === label)) {
  await reset(`${label} is not applied`);
  return;
}

// Only the labeling run creates a waiver. Its sender and the latest labeler must both have write access.
const waiving = !dispatched && action === 'labeled' && eventLabel === label;
const events = await github.paginate(github.rest.issues.listEvents, {
  owner, repo, issue_number: pr.number, per_page: 100,
});
// Events have no guaranteed order: take the newest labeling by time; a tie between actors resets.
const labelings = events.filter((e) => e.event === 'labeled' && e.label?.name === label);
const newest = Math.max(...labelings.map((e) => Date.parse(e.created_at)));
const newestActors = [...new Set(labelings.
  filter((e) => Date.parse(e.created_at) === newest).
  map((e) => e.actor?.login || ''))];
if (newestActors.length > 1) {
  await reset(`${label} was applied by ${newestActors.join(', ')} at the same time`);
  return;
}
const latest = newestActors[0] || '';
const approver = waiving ? (context.payload.sender?.login || '') : latest;
const required = [...new Set([approver, latest].filter(Boolean))];
for (const user of required.length ? required : ['']) {
  if (!(await hasWriteAccess(user))) {
    await reset(`${label} was applied by '${user}', who lacks write access`);
    return;
  }
}

// The waiver covers only the labeled commit; a manual run never creates one.
if (!waiving) {
  core.info(`Fork PR #${pr.number}: ${label} by @${approver} stands; nothing new to post.`);
  return;
}
const labeledSha = context.payload.pull_request.head.sha;
if (labeledSha !== pr.head.sha) {
  core.info(`Fork PR #${pr.number} moved from ${labeledSha} to ${pr.head.sha} since it was labeled; not waiving the new commit.`);
  return;
}

core.setOutput('mode', 'success');
core.setOutput('approver', approver);
core.info(`Fork PR #${pr.number} @ ${pr.head.sha}: waiving E2E on behalf of @${approver}.`);

const {E2E_OS_STATUS_CONTEXTS, E2E_POLICY_STATUS_CONTEXTS} = require('./e2e/utils/github-actions.js');
const {owner, repo} = context.repo;
const waive = process.env.MODE === 'success';
// Present only in descriptions written here, so a reset never touches a real result.
const MARKER = 'e2e overridden';
const targetUrl = `${context.serverUrl}/${owner}/${repo}/actions/runs/${context.runId}`;

// A reset must also reach commits waived earlier: the author could push away and back.
// Every waiver ran this workflow on the PR's head at the time, so its earlier runs list them.
const shas = [process.env.HEAD_SHA];
if (!waive && process.env.HEAD_REPO) {
  const runs = await github.paginate(github.rest.actions.listWorkflowRuns, {
    owner, repo, workflow_id: 'e2e-fork-policy.yml',
    event: 'pull_request_target', branch: process.env.HEAD_REF, per_page: 100,
  });
  for (const run of runs) {
    if (run.head_repository?.full_name === process.env.HEAD_REPO && !shas.includes(run.head_sha)) {
      shas.push(run.head_sha);
    }
  }
}

const failures = [];
for (const sha of shas) {
  const statuses = await github.paginate(github.rest.repos.listCommitStatusesForRef, {
    owner, repo, ref: sha, per_page: 100,
  });
  // Newest first: the first entry per context is its current state.
  const latest = new Map();
  for (const status of statuses) {
    if (!latest.has(status.context)) {
      latest.set(status.context, status);
    }
  }

  for (const statusContext of [...E2E_OS_STATUS_CONTEXTS, ...E2E_POLICY_STATUS_CONTEXTS]) {
    const current = latest.get(statusContext);
    let state;
    let description;
    if (waive) {
      if (current?.state === 'success') {
        continue;
      }
      state = 'success';
      description = `${MARKER} by @${process.env.APPROVER} (fork PR, E2E not run)`;
    } else {
      if (!current?.description?.includes(MARKER)) {
        continue;
      }
      state = 'pending';
      description = 'E2E/Override missing or not applied by a writer; fork PRs need it to merge';
    }
    // Retry once: a manual re-check can't fill in a context missed on a transient error.
    let lastError;
    for (let attempt = 0; attempt < 2; attempt++) {
      try {
        await github.rest.repos.createCommitStatus({
          owner, repo, sha, state, context: statusContext,
          description: description.substring(0, 140),
          ...(waive ? {target_url: targetUrl} : {}),
        });
        core.info(`Published ${state} for ${statusContext} on ${sha}`);
        lastError = undefined;
        break;
      } catch (err) {
        lastError = err;
      }
    }
    if (lastError) {
      failures.push(`${statusContext} on ${sha}: ${lastError.message}`);
    }
  }
}
if (failures.length > 0) {
  throw new Error(`Failed to publish ${failures.length} status(es): ${failures.join('; ')}`);
}

const {updateInitialOsStatuses} = require('./e2e/utils/github-actions.js');
await updateInitialOsStatuses({
  github,
  context,
  sha: process.env.DESKTOP_SHA,
  platforms: JSON.parse(process.env.PLATFORMS || '[]'),
  includePolicy: true,
});

const {E2E_POLICY_OS_LIST} = require('./e2e/utils/github-actions.js');
const {reportUrl, status, stats} = await require('./e2e/utils/tsio-report-status.js')({
  core, context, github,
  compositeIdentity: JSON.parse(process.env.TSIO_COMPOSITE_IDENTITY),
  totalReportsExpected: parseInt(process.env.TSIO_TOTAL_REPORTS_EXPECTED, 10),
  upstreamJobsSucceeded: process.env.UPSTREAM_JOBS_SUCCEEDED === 'true',
  perOsCommitStatuses: true,
  expectedOs: null,
  expectedPolicyOs: E2E_POLICY_OS_LIST,
  failOnTestFailures: true,
  notifyChannel: false,
  readyWhenPolicy: true,
  minReports: E2E_POLICY_OS_LIST.length,
});
core.info(`TSIO policy ${reportUrl}: ${status} (${JSON.stringify(stats)})`);

const {canonicalizeOs, E2E_POLICY_OS_LIST} = require('./e2e/utils/github-actions.js');
const compositeIdentity = JSON.parse(process.env.TSIO_COMPOSITE_IDENTITY);
const platforms = JSON.parse(process.env.PLATFORMS || '[]');
const expectedOs = [...new Set(
  platforms.map((p) => canonicalizeOs(p.platform || p.os, p.runner)).filter(Boolean),
)];
// Master channel alerts wait for AI triage: master-e2e-verdict
// posts them once tsio-triage has judged the failures (silent
// when cleared, red only when blocking). PR alerts post here.
// Outputs are set before rethrowing so the verdict job still
// gets the settled TSIO snapshot on a red run.
const pickDetail = (d) => ({
  status: d?.status,
  test_stats: d?.test_stats,
  reports: (d?.reports || []).map((r) => ({id: r.id, gh_job_name: r.gh_job_name, display_name: r.display_name, status: r.status})),
});
let result;
try {
  result = await require('./e2e/utils/tsio-report-status.js')({
    core, context, github,
    compositeIdentity,
    totalReportsExpected: parseInt(process.env.TSIO_TOTAL_REPORTS_EXPECTED, 10),
    upstreamJobsSucceeded: process.env.UPSTREAM_JOBS_SUCCEEDED === 'true',
    perOsCommitStatuses: false,
    expectedOs,
    expectedPolicyOs: E2E_POLICY_OS_LIST,
    failOnTestFailures: true,
    notifyChannel: compositeIdentity.name !== 'desktop-master',
  });
} catch (error) {
  core.setOutput('report-url', error.reportUrl || '');
  core.setOutput('stats', JSON.stringify(error.stats || {}));
  core.setOutput('detail', JSON.stringify(pickDetail(error.detail)));
  throw error;
}
core.setOutput('report-url', result.reportUrl || '');
core.setOutput('stats', JSON.stringify(result.stats || {}));
core.setOutput('detail', JSON.stringify(pickDetail(result.detail)));
core.info(`TSIO report ${result.reportUrl}: ${result.status} (${JSON.stringify(result.stats)})`);

const fs = require('fs');
const path = require('path');
const {notifyCmtChannel} = require('./e2e/utils/cmt-channel-notify.js');
const {redStatusNotCleared} = require('./e2e/utils/cmt-triage-verdict.js');
const {resolveMasterMergeContext} = require('./e2e/utils/tsio-report-status.js');

const compositeIdentity = JSON.parse(process.env.TSIO_COMPOSITE_IDENTITY);

let detail = {};
let stats = {};
try {
  detail = JSON.parse(process.env.DETAIL || '{}');
  stats = JSON.parse(process.env.STATS || '{}');
} catch {
  core.warning('Could not parse TSIO summary outputs; the alert falls back to job results');
}

let triageLanes = [];
try {
  triageLanes = fs.readdirSync('e2e-triage-verdicts')
    .filter((file) => file.endsWith('.json'))
    .map((file) => JSON.parse(fs.readFileSync(path.join('e2e-triage-verdicts', file), 'utf8')));
} catch (error) {
  core.info(`No triage verdict artifacts: ${error.message}`);
}

const mergeContext = await resolveMasterMergeContext({github, context, compositeIdentity, core});
let statusResults = {};
try {
  statusResults = JSON.parse(process.env.STATUS_RESULTS || '{}');
} catch {
  core.warning('Could not parse the status job results; the alert reads TSIO alone');
}
const hasFailures = redStatusNotCleared(statusResults, triageLanes) || (stats.failed || 0) > 0 || (detail.reports || []).some((report) => report.status === 'failed');
await notifyCmtChannel({
  core,
  baseUrl: process.env.TSIO_BASE_URL,
  compositeIdentity,
  detail,
  reportUrl: process.env.REPORT_URL || '',
  upstreamJobsSucceeded: process.env.UPSTREAM_JOBS_SUCCEEDED === 'true',
  hasFailures,
  webhookUrl: process.env.MATTERMOST_MASTER_HEALTH_WEBHOOK_URL || '',
  mergedPr: mergeContext.mergedPr,
  headCommit: mergeContext.headCommit,
  triageLanes,
  statusResults,
});

// Use pr_number if provided directly by the dispatcher (e.g. Matterwick)
let prNumber = parseInt(process.env.PR_NUMBER) || null;

// Fall back to looking up the PR by head branch when pr_number was not passed
if (!prNumber) {
  const run = await github.rest.actions.getWorkflowRun({
    owner: context.repo.owner,
    repo: context.repo.repo,
    run_id: context.runId,
  });
  const branchName = run.data.head_branch;
  if (branchName) {
    const headOwner = run.data.head_repository?.owner?.login || context.repo.owner;
    const prs = await github.rest.pulls.list({
      owner: context.repo.owner,
      repo: context.repo.repo,
      state: 'open',
      head: `${headOwner}:${branchName}`,
    });
    if (prs.data && prs.data.length > 0) {
      const matchingPr = prs.data.find((pr) => pr.head && pr.head.sha === run.data.head_sha);
      prNumber = (matchingPr || prs.data[0]).number;
    }
  }
}

if (prNumber) {
  try {
    await github.rest.issues.removeLabel({
      issue_number: prNumber,
      owner: context.repo.owner,
      repo: context.repo.repo,
      name: 'E2E/Run',
    });
  } catch (error) {
    if (error.status !== 404) {
      throw error;
    }
    console.log('E2E/Run label already removed');
  }
} else {
  console.log('Label removal skipped - could not find associated PR');
}

const { removeE2ELabel } = require('./e2e/utils/github-actions.js');
// Pass the original test workflow's run ID so removeE2ELabel can
// look up the dispatching branch and find the associated PR.
await removeE2ELabel({
  github,
  context: {
    repo: context.repo,
    runId: ${{ github.event.workflow_run.id }},
  },
});

const {reportUrl, status, stats} = await require('./e2e/utils/tsio-report-status.js')({
  core, context, github,
  compositeIdentity: JSON.parse(process.env.TSIO_COMPOSITE_IDENTITY),
  totalReportsExpected: parseInt(process.env.TSIO_TOTAL_REPORTS_EXPECTED, 10),
  upstreamJobsSucceeded: process.env.UPSTREAM_JOBS_SUCCEEDED === 'true',
  perOsCommitStatuses: true,
  expectedOs: [process.env.READY_WHEN_OS],
  notifyChannel: false,
  readyWhenOs: process.env.READY_WHEN_OS,
  minReports: parseInt(process.env.MIN_REPORTS, 10),
});
core.info(`TSIO ${process.env.READY_WHEN_OS} ${reportUrl}: ${status} (${JSON.stringify(stats)})`);

const {markE2EStatusesCancelled, cancelActiveE2ERuns} = require('./e2e/utils/github-actions.js');
const { owner, repo } = context.repo;
const issue_number = context.issue.number;
const pr = context.payload.pull_request;

await cancelActiveE2ERuns({
  github,
  context,
  prNumber: issue_number,
  headBranch: pr.head.ref,
});

// Current labels decide (see Honor step): if the waiver was
// applied in the same edit that removed E2E/Run, it owns the
// statuses — do not overwrite its success with `error`.
const currentLabels = await github.paginate(github.rest.issues.listLabelsOnIssue, {
  owner,
  repo,
  issue_number,
  per_page: 100,
});
if (currentLabels.some((label) => label.name === 'E2E/Override')) {
  core.info(`PR #${issue_number} has E2E/Override — skipping cancelled status update.`);
  return;
}

await markE2EStatusesCancelled({
  github,
  context,
  sha: pr.head.sha,
  reason: 'E2E cancelled (E2E/Run label removed)',
});

const {cancelActiveE2ERuns, markE2EStatusesCancelled} = require('./e2e/utils/github-actions.js');
const { owner, repo } = context.repo;
const issue_number = context.issue.number;
const pr = context.payload.pull_request;

// Decide from current labels, not this event: a paired
// E2E/Run removal may be handled before or after us, and the
// waiver may already have been taken back. Inlined on purpose —
// this job checks out the base ref, so it can only require()
// helpers that already exist on master.
const currentLabels = await github.paginate(github.rest.issues.listLabelsOnIssue, {
  owner,
  repo,
  issue_number,
  per_page: 100,
});
if (!currentLabels.some((label) => label.name === 'E2E/Override')) {
  core.info(`PR #${issue_number} no longer has E2E/Override — skipping waiver.`);
  return;
}

try {
  await github.rest.issues.removeLabel({
    owner,
    repo,
    issue_number,
    name: 'E2E/Run',
  });
} catch (error) {
  if (error.status !== 404) {
    throw error;
  }
}

await cancelActiveE2ERuns({
  github,
  context,
  prNumber: issue_number,
  headBranch: pr.head.ref,
});

// Re-read immediately before the final status update: the
// waiver may have been removed while runs were being cancelled.
const latestLabels = await github.paginate(github.rest.issues.listLabelsOnIssue, {
  owner,
  repo,
  issue_number,
  per_page: 100,
});
if (!latestLabels.some((label) => label.name === 'E2E/Override')) {
  core.info(`PR #${issue_number} lost E2E/Override before the waiver posted — skipping.`);
  return;
}

await markE2EStatusesCancelled({
  github,
  context,
  sha: pr.head.sha,
  state: 'success',
  reason: 'E2E waived (E2E/Override label applied) — no tests ran',
});

const { owner, repo } = context.repo;
const issue_number = context.issue.number;

// Current labels, inlined (base-ref checkout; see Honor step).
const currentLabels = await github.paginate(github.rest.issues.listLabelsOnIssue, {
  owner,
  repo,
  issue_number,
  per_page: 100,
});
if (currentLabels.some((label) => label.name === 'E2E/Override')) {
  core.info(`PR #${issue_number} has E2E/Override again — skipping re-arm.`);
  return;
}

try {
  await github.rest.issues.removeLabel({
    owner,
    repo,
    issue_number,
    name: 'E2E/Run',
  });
} catch (error) {
  if (error.status !== 404) {
    throw error;
  }
}

// Re-read immediately before re-arming: the waiver may have
// been re-applied while the stale run label was being removed.
const latestLabels = await github.paginate(github.rest.issues.listLabelsOnIssue, {
  owner,
  repo,
  issue_number,
  per_page: 100,
});
if (latestLabels.some((label) => label.name === 'E2E/Override')) {
  core.info(`PR #${issue_number} regained E2E/Override before re-arm — skipping.`);
  return;
}

await github.rest.issues.addLabels({
  owner,
  repo,
  issue_number,
  labels: ['E2E/Run'],
});

const {cancelActiveE2ERuns, markE2EStatusesCancelled} = require('./e2e/utils/github-actions.js');
const { owner, repo } = context.repo;
const issue_number = context.issue.number;
const pr = context.payload.pull_request;

const labels = await github.paginate(github.rest.issues.listLabelsOnIssue, {
  owner,
  repo,
  issue_number,
  per_page: 100,
});
const labelNames = labels.map((label) => label.name);

if (labelNames.includes('E2E/Override')) {
  core.info(`PR #${issue_number} has E2E/Override — skipping E2E/Run refresh.`);

  if (labelNames.includes('E2E/Run')) {
    try {
      await github.rest.issues.removeLabel({
        owner,
        repo,
        issue_number,
        name: 'E2E/Run',
      });
    } catch (error) {
      if (error.status !== 404) {
        throw error;
      }
    }
  }

  await cancelActiveE2ERuns({
    github,
    context,
    prNumber: issue_number,
    headBranch: pr.head.ref,
  });
  await markE2EStatusesCancelled({
    github,
    context,
    sha: pr.head.sha,
    state: 'success',
    reason: 'E2E waived (E2E/Override label active) — no tests ran',
  });
  return;
}

await cancelActiveE2ERuns({
  github,
  context,
  prNumber: issue_number,
  headBranch: pr.head.ref,
});

try {
  await github.rest.issues.removeLabel({
    owner,
    repo,
    issue_number,
    name: 'E2E/Run',
  });
} catch (error) {
  if (error.status !== 404) {
    throw error;
  }
}

await github.rest.issues.addLabels({
  owner,
  repo,
  issue_number,
  labels: ['E2E/Run'],
});

const run = context.payload.workflow_run;
const {owner, repo} = context.repo;
const branch = run.head_branch || '';
const {data: prs} = branch ? await github.rest.pulls.list({owner, repo, state: 'open', head: `${owner}:${branch}`, per_page: 1}) : {data: []};
if (!prs.length) {
  core.setOutput('superseded', 'false');
  return;
}
// A run's pr_number input: '' for a run dispatched without one, null when it cannot be read.
const prOf = async (runId) => {
  try {
    const {data: {jobs}} = await github.rest.actions.listJobsForWorkflowRun({owner, repo, run_id: runId, per_page: 100});
    const job = jobs.find((j) => j.name.startsWith('prepare-matrix'));
    if (!job) {
      return null;
    }
    const {data: log} = await github.rest.actions.downloadJobLogsForWorkflowRun({owner, repo, job_id: job.id});
    const found = (/^\S+\s+PR_NUMBER:[ \t]*(\d*)[ \t]*$/m).exec(typeof log === 'string' ? log : String(log));
    return found ? found[1] : null;
  } catch (e) {
    core.info(`Could not read run ${runId}'s pr_number: ${e.message}`);
    return null;
  }
};
const own = await prOf(run.id);
if (own === '') {
  core.info(`${run.html_url} was dispatched without pr_number: keyed by SHA, no newer run cancels it.`);
  core.setOutput('superseded', 'false');
  return;
}
const {data: {workflow_runs: runs}} = await github.rest.actions.listWorkflowRuns({
  owner, repo, workflow_id: run.workflow_id, branch, per_page: 20,
});
// Unknown on either side counts as the same PR: re-running could cancel that run.
let newer = null;
for (const r of runs.filter((r) => r.run_number > run.run_number)) {
  const pr = await prOf(r.id);
  if ((pr === null || own === null) ? pr !== '' : pr === own) {
    newer = r;
    break;
  }
}
const prHead = prs[0].head.sha;
let reason = '';
if (newer) {
  reason = `a newer run of this workflow for the same PR on ${branch} exists: ${newer.html_url}`;
} else if (prHead && prHead !== run.head_sha) {
  reason = `PR #${prs[0].number} is now at ${prHead.slice(0, 7)}; this run tested ${run.head_sha.slice(0, 7)}`;
}
if (reason) {
  core.notice(`Not re-running ${run.html_url}: ${reason}.`);
}
core.setOutput('superseded', reason ? 'true' : 'false');
